function solve(a, b) {
  function parse(s) {
    const parts = s.trim().split(/[-+]/);
    const core = parts[0].split('.').map(Number);
    let preRelease = null;
    let build = null;
    if (parts.length > 1) {
      const rest = parts.slice(1).join('');
      if (rest.includes('-')) {
        const [pre, buildStr] = rest.split('-');
        preRelease = pre.split('.');
        build = buildStr ? buildStr.split('.') : null;
      } else if (rest.includes('+')) {
        const [pre, buildStr] = rest.split('+');
        preRelease = pre.split('.');
        build = buildStr ? buildStr.split('.') : null;
      }
    }
    return {
      core: core,
      preRelease,
      build
    };
  }

  const p1 = parse(a);
  const p2 = parse(b);

  for (let i = 0; i < 3; i++) {
    if (p1.core[i] > p2.core[i]) return 1;
    if (p1.core[i] < p2.core[i]) return -1;
  }

  if (!p1.preRelease && !p2.preRelease) return 0;
  if (!p1.preRelease) return 1;
  if (!p2.preRelease) return -1;

  for (let i = 0; i < Math.max(p1.preRelease.length, p2.preRelease.length); i++) {
    const a = p1.preRelease[i] || 0;
    const b = p2.preRelease[i] || 0;
    const na = a.replace(/^0+/, '') || '0';
    const nb = b.replace(/^0+/, '') || '0';
    if (na > nb) return 1;
    if (na < nb) return -1;
  }

  return 0;
}
