function solve(a, b) {
  const parse = (s) => {
    const m = s.match(/^(\d+)\.(\d+)\.(\d+)(?:-([^\+]+))?(?:\+([^\+]+))?$/);
    if (!m) return null;
    return {
      major: parseInt(m[1], 10),
      minor: parseInt(m[2], 10),
      patch: parseInt(m[3], 10),
      prerelease: m[4] || null,
      build: m[5] || null,
    };
  };

  const pa = parse(a);
  const pb = parse(b);
  if (!pa || !pb) return 0;

  if (pa.major !== pb.major) return pa.major < pb.major ? -1 : 1;
  if (pa.minor !== pb.minor) return pa.minor < pb.minor ? -1 : 1;
  if (pa.patch !== pb.patch) return pa.patch < pb.patch ? -1 : 1;

  if (pa.prerelease === null && pb.prerelease === null) return 0;
  if (pa.prerelease === null) return 1;
  if (pb.prerelease === null) return -1;

  const paParts = pa.prerelease.split('.');
  const pbParts = pb.prerelease.split('.');
  const len = Math.max(paParts.length, pbParts.length);
  for (let i = 0; i < len; i++) {
    const paPart = paParts[i] || '';
    const pbPart = pbParts[i] || '';
    const paNum = parseInt(paPart, 10);
    const pbNum = parseInt(pbPart, 10);
    const paIsNum = !isNaN(paNum) && paPart.length === paPart.replace(/\d/, '').length;
    const pbIsNum = !isNaN(pbNum) && pbPart.length === pbPart.replace(/\d/, '').length;

    if (paIsNum && pbIsNum) {
      if (paNum !== pbNum) return paNum < pbNum ? -1 : 1;
    } else if (paIsNum) {
      return -1;
    } else if (pbIsNum) {
      return 1;
    } else {
      if (paPart !== pbPart) return paPart < pbPart ? -1 : 1;
    }
  }

  return 0;
}
