  function parse() {
    skipSpaces();
    if (i >= expr.length) throw new Error("Unexpected end");
    let val = parseFactor();
    while (i < expr.length) {
      const ch = expr[i];
      if (ch === ' ' || ch === '\t' || ch === '\n' || ch === '\r') {
        i++;
        continue;
      }
      if (ch === '+') {
        i++; skipSpaces();
        val += parseFactor();
      } else if (ch === '-') {
        i++; skipSpaces();
        val -= parseFactor();
      } else if (ch === '*') {
        i++; skipSpaces();
        val *= parseFactor();
      } else if (ch === '/') {
        i++; skipSpaces();
        const divisor = parseFactor();
        if (divisor === 0) throw new Error("Division by zero");
        val /= divisor;
      } else {
        break;
      }
    }
    return val;
  }

  function parseFactor() {
    skipSpaces();
    if (i >= expr.length) throw new Error("Unexpected end");
    const ch = expr[i];
    if (ch === '(') {
      i++; skipSpaces();
      const val = parse();
      if (i >= expr.length || expr[i] !== ')') throw new Error("Missing closing parenthesis");
      i++; skipSpaces();
      return val;
    }
    // unary minus
    if (ch === '-') {
      i++;
      return -parseFactor();
    }
    let val = 0;
    while (i < expr.length && expr[i] >= '0' && expr[i] <= '9') {
