    function skipWhitespace() {
        while (pos < expr.length && expr[pos] === ' ') pos++;
    }

    function parseExpr() {
        let left = parseTerm();
        while (pos < expr.length) {
            skipWhitespace();
            const c = expr[pos];
            if (c === '+' || c === '-') {
                pos++;
                const right = parseTerm();
                left = c === '+' ? left + right : left - right;
            } else break;
        }
        return left;
    }

    function parseTerm() {
        let left = parseFactor();
        while (pos < expr.length) {
            skipWhitespace();
            const c = expr[pos];
            if (c === '*' || c === '/') {
                pos++;
                const right = parseFactor();
                left = c === '*' ? left * right : left / right;
            } else break;
        }
        return left;
    }

    function parseFactor() {
        skipWhitespace();
        const c = expr[pos];
        if (c === '(') {
            pos++;
            const val = parseExpr();
            pos++; // skip ')'
            return val;
        }
        if (c === '-') {
            pos++;
            return -parseFactor();
        }
        let num = 0;
        while (pos < expr.length && /d/.test(expr[pos])) {
            num = num * 10 + parseInt(expr[pos], 10);
            pos++;
        }
