function solve(n, arestas) {
  const adj = Array.from({ length: n }, () => []);
  for (const [a, b] of arestas) {
    if (a >= 0 && a < n && b >= 0 && b < n) adj[a].push(b);
  }

  const inDegree = new Array(n).fill(0);
  for (let a = 0; a < n; a++) {
    for (const b of adj[a]) {
      if (b >= 0 && b < n) inDegree[b]++;
    }
  }

  // Min-heap for lexicographically smallest topological order
  const heap = new MinHeap();
  for (let i = 0; i < n; i++) {
    if (inDegree[i] === 0) heap.push(i);
  }

  const order = [];
  while (heap.size() > 0) {
    const u = heap.pop();
    order.push(u);
    for (const v of adj[u]) {
      if (v >= 0 && v < n) {
        inDegree[v]--;
        if (inDegree[v] === 0) heap.push(v);
      }
    }
  }

  return order.length === n ? order : null;
}

class MinHeap {
  constructor() {
    this.arr = [];
  }
  push(val) {
    this.arr.push(val);
    this._bubbleUp(this.arr.length - 1);
  }
  pop() {
    const top = this.arr[0];
    const last = this.arr.pop();
    if (this.arr.length > 0) this._bubbleDown(0);
    return top;
  }
  _bubbleUp(i) {
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (this.arr[p] > this.arr[i]) {
        [this.arr[p], this.arr[i]] = [this.arr[i], this.arr[p]];
        i = p;
      } else break;
    }
  }
  _bubbleDown(i) {
    const n = this.arr.length;
    while (true) {
      let smallest = i;
      const l = 2 * i + 1, r = 2 * i + 2;
      if (l < n && this.arr[l] < this.arr[smallest]) smallest = l;
      if (r < n && this.arr[r] < this.arr[smallest]) smallest = r;
      if (smallest !== i) {
        [this.arr[smallest], this.arr[i]] = [this.arr[i], this.arr[smallest]];
        i = smallest;
      } else break;
    }
  }
  size() {
    return this.arr.length;
  }
}
