function solve(precos) {
  const n = precos.length;
  if (n <= 1) return 0;

  // Máximo de lucro com no máximo 2 transações até o dia i
  let minPreco = precos[0];
  const maxLucroAte = new Array(n);
  let maxLucro = 0;
  for (let i = 0; i < n; i++) {
    minPreco = Math.min(minPreco, precos[i]);
    maxLucro = Math.max(maxLucro, precos[i] - minPreco);
    maxLucroAte[i] = maxLucro;
  }

  // Máximo de lucro com no máximo 2 transações a partir do dia i
  let maxPreco = precos[n - 1];
  const maxLucroDe = new Array(n);
  maxLucroDe[n - 1] = 0;
  let maxLucroFrom = 0;
  for (let i = n - 2; i >= 0; i--) {
    maxPreco = Math.max(maxPreco, precos[i]);
    maxLucroFrom = Math.max(maxLucroFrom, maxPreco - precos[i]);
    maxLucroDe[i] = maxLucroFrom;
  }

  // Maximizar a soma das duas partes
  let lucroMax = 0;
  for (let i = 0; i < n; i++) {
    lucroMax = Math.max(lucroMax, maxLucroAte[i] + maxLucroDe[i]);
  }

  return lucroMax;
}
